<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/app/Support/result_repository_links.php';use App\Core\Database;$pdo=Database::connection();
$dance=(string)($_GET['dance']??'bachata');if(!in_array($dance,['bachata','salsa','dance_cup'],true))$dance='bachata';$segment=(string)($_GET['segment']??'participants');if(!in_array($segment,['participants','repository'],true))$segment='participants';$query=trim((string)($_GET['q']??''));$eventId=max(0,(int)($_GET['event']??0));$events=$pdo->query("SELECT id,name,event_date FROM bdc_events ORDER BY event_date DESC,id DESC")->fetchAll();$rows=[];$repositoryRows=[];$participantSummaries=[];$cupRows=[];
function danceResultLabel(string $dance):string{return match($dance){'salsa'=>'Salsa','dance_cup'=>'BDC Dance Cup',default=>'Bachata'};}function repositoryUrl(array $row):?string{$link=repository_document_link($row,dirname(__DIR__),rtrim(url('/'),'/'));return !empty($link['exists'])?(string)$link['url']:null;}
if($dance==='dance_cup'){$sql="SELECT d.*,e.name event_name,e.event_date,c.id competitor_id,c.exact_name,c.bdc_id,c.country,c.photo_url FROM bdc_dance_cup_results d JOIN bdc_events e ON e.id=d.event_id LEFT JOIN bdc_competitors c ON c.id=d.competitor_id WHERE 1=1";$params=[];if($eventId>0){$sql.=' AND d.event_id=:event';$params['event']=$eventId;}if($query!==''){$sql.=' AND (d.entrant_name LIKE :q OR d.category_name LIKE :q2 OR e.name LIKE :q3 OR c.bdc_id LIKE :q4)';$like='%'.$query.'%';$params+=['q'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like];}$sql.=' ORDER BY e.event_date DESC,CASE WHEN d.placement IS NULL THEN 999999 ELSE d.placement END,d.id DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$cupRows=$stmt->fetchAll();}
elseif($segment==='repository'){$sql="SELECT d.*,e.name event_name,e.event_date FROM bdc_result_documents d LEFT JOIN bdc_events e ON e.id=d.event_id WHERE d.status='published'";$params=[];if($eventId>0){$sql.=' AND d.event_id=:event';$params['event']=$eventId;}if($query!==''){$sql.=' AND (d.title LIKE :document_query OR e.name LIKE :event_query)';$params['document_query']='%'.$query.'%';$params['event_query']='%'.$query.'%';}$sql.=' ORDER BY COALESCE(e.event_date,DATE(d.created_at)) DESC,d.id DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);foreach($stmt->fetchAll() as $row){$category=(string)($row['document_category']??'');if(!in_array($category,['heats','finals','points'],true))continue;$groupKey=!empty($row['event_id'])?'event:'.(int)$row['event_id']:'document:'.(int)$row['id'];if(!isset($repositoryRows[$groupKey]))$repositoryRows[$groupKey]=['event_name'=>(string)($row['event_name']?:$row['title']),'event_date'=>(string)($row['event_date']??''),'documents'=>[]];if(!isset($repositoryRows[$groupKey]['documents'][$category]))$repositoryRows[$groupKey]['documents'][$category]=$row;}}
else{$sql="SELECT r.*,c.exact_name,c.bdc_id,c.photo_url,c.country,e.name event_name,e.event_date FROM bdc_participant_results r JOIN bdc_competitors c ON c.id=r.competitor_id JOIN bdc_events e ON e.id=r.event_id WHERE c.status='active' AND r.dance_style=:dance";$params=['dance'=>$dance];if($eventId>0){$sql.=' AND r.event_id=:event';$params['event']=$eventId;}if($query!==''){$sql.=' AND (c.exact_name LIKE :name_query OR c.bdc_id LIKE :id_query OR e.name LIKE :event_query)';$like='%'.$query.'%';$params+=['name_query'=>$like,'id_query'=>$like,'event_query'=>$like];}$sql.=' ORDER BY e.event_date DESC,r.id DESC LIMIT 500';$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();if($query!==''&&$rows){$competitorIds=array_values(array_unique(array_map(static fn(array $row):int=>(int)$row['competitor_id'],$rows)));$ph=implode(',',array_fill(0,count($competitorIds),'?'));$summarySql="SELECT c.id,c.exact_name,c.bdc_id,c.photo_url,c.country,COALESCE(SUM(CASE WHEN p.division='novice' THEN p.points ELSE 0 END),0) novice_points,COALESCE(SUM(CASE WHEN p.division='intermediate' THEN p.points ELSE 0 END),0) intermediate_points,COALESCE(SUM(CASE WHEN p.division='advanced' THEN p.points ELSE 0 END),0) advanced_points FROM bdc_competitors c LEFT JOIN bdc_point_transactions p ON p.competitor_id=c.id AND p.dance_style=? WHERE c.id IN ($ph) GROUP BY c.id,c.exact_name,c.bdc_id,c.photo_url,c.country ORDER BY intermediate_points DESC,novice_points DESC,c.exact_name";$summaryStmt=$pdo->prepare($summarySql);$summaryStmt->execute(array_merge([$dance],$competitorIds));$participantSummaries=$summaryStmt->fetchAll();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Results</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f6f8}.hero{background:linear-gradient(135deg,#111827,#27272a);color:#fff}.results-card{border:0;border-radius:16px;box-shadow:0 8px 28px rgba(15,23,42,.08)}.tabs{margin-top:-28px}.participant-summary-photo{width:58px;height:58px;border-radius:50%;object-fit:cover;background:#eceff3}@media(max-width:575px){.discipline-tabs .btn{flex:1 1 100%}}</style></head><body><section class="hero py-5"><div class="container d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><div class="text-uppercase small opacity-75">Bachata Dance Council</div><h1 class="display-6 fw-bold mb-2">Results</h1><p class="mb-0 opacity-75">Bachata, Salsa and BDC Dance Cup histories are kept separate.</p></div><a class="btn btn-outline-light" href="<?=e(url('/'))?>">BDC Home</a></div></section><main class="container pb-5"><section class="card results-card tabs mb-4"><div class="card-body"><div class="d-flex gap-2 flex-wrap discipline-tabs"><?php foreach(['bachata'=>'Bachata','salsa'=>'Salsa','dance_cup'=>'BDC Dance Cup'] as $value=>$label):?><a class="btn <?=$dance===$value?'btn-dark':'btn-outline-dark'?>" href="?dance=<?=$value?>&amp;segment=participants"><?=$label?></a><?php endforeach;?></div></div></section><?php if($dance!=='dance_cup'):?><nav class="nav nav-pills gap-2 mb-3"><a class="nav-link <?=$segment==='participants'?'active':''?>" href="?dance=<?=$dance?>&amp;segment=participants">Participant Results</a><a class="nav-link <?=$segment==='repository'?'active':''?>" href="?dance=<?=$dance?>&amp;segment=repository">Result Repository</a></nav><?php endif;?><section class="card results-card mb-4"><div class="card-body"><form method="get" class="row g-3 align-items-end"><input type="hidden" name="dance" value="<?=e($dance)?>"><input type="hidden" name="segment" value="<?=e($segment)?>"><div class="col-md-6"><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($query)?>" placeholder="Competitor, BDC ID, category or event"></div><div class="col-md-4"><label class="form-label">Event</label><select class="form-select" name="event"><option value="0">All events</option><?php foreach($events as $event):?><option value="<?=(int)$event['id']?>" <?=$eventId===(int)$event['id']?'selected':''?>><?=e($event['name'])?><?=!empty($event['event_date'])?' · '.e($event['event_date']):''?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-dark w-100">Search</button></div></form></div></section>
<?php if($dance==='dance_cup'):?><section class="card results-card"><div class="card-header bg-white"><strong>BDC Dance Cup Results</strong><div class="small text-muted">Placements only. No BDC points are allocated.</div></div><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Date</th><th>Event</th><th>Entrant</th><th>BDC ID</th><th>Category</th><th>Placement</th></tr></thead><tbody><?php foreach($cupRows as $row):?><tr><td><?=e($row['event_date']?:'—')?></td><td><?=e($row['event_name'])?></td><td><?php if($row['competitor_id']):?><a class="fw-semibold text-dark" href="<?=e(url('/competitor/?id='.(int)$row['competitor_id'].'&dance=dance_cup'))?>"><?=e($row['entrant_name'])?></a><?php else:?><?=e($row['entrant_name'])?><?php endif;?></td><td><?=e($row['bdc_id']?:'—')?></td><td><?=e($row['category_name']?:'—')?></td><td class="fw-bold"><?=e($row['placement']?:'—')?></td></tr><?php endforeach;?><?php if(!$cupRows):?><tr><td colspan="6" class="text-center text-muted py-5">No BDC Dance Cup results yet.</td></tr><?php endif;?></tbody></table></div></section><?php elseif($segment==='repository'):?><section class="card results-card"><div class="card-header bg-white"><strong><?=e(danceResultLabel($dance))?> Result Repository</strong><?php if($dance==='salsa'):?><div class="small text-muted">Legacy repository documents are Bachata-era unless separately classified in a later repository update.</div><?php endif;?></div><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Event</th><th>Heats</th><th>Final</th><th>Points</th></tr></thead><tbody><?php foreach($repositoryRows as $repositoryRow):?><tr><td><strong><?=e($repositoryRow['event_name'])?></strong><div class="small text-muted"><?=e($repositoryRow['event_date'])?></div></td><?php foreach(['heats'=>'Heats','finals'=>'Final','points'=>'Points'] as $category=>$label):$document=$repositoryRow['documents'][$category]??null;$documentUrl=$document?repositoryUrl($document):null;?><td><?php if($documentUrl):?><a class="btn btn-sm btn-outline-dark" href="<?=e($documentUrl)?>" target="_blank" rel="noopener">View <?=$label?></a><?php else:?>—<?php endif;?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$repositoryRows):?><tr><td colspan="4" class="text-center text-muted py-5">No published documents found.</td></tr><?php endif;?></tbody></table></div></section><?php else:?><?php if($participantSummaries):?><section class="card results-card mb-4"><div class="card-body"><div class="text-uppercase small text-muted fw-semibold mb-3"><?=e(danceResultLabel($dance))?> Points</div><div class="row g-3"><?php foreach($participantSummaries as $summary):?><div class="col-12 col-lg-6"><div class="border rounded-3 p-3"><div class="d-flex gap-3 align-items-center"><img class="participant-summary-photo" src="<?=e($summary['photo_url']?:url('/public/assets/img/default-competitor.svg'))?>" alt=""><div><a class="fw-bold text-dark" href="<?=e(url('/competitor/?id='.(int)$summary['id'].'&dance='.$dance))?>"><?=e($summary['exact_name'])?></a><div class="small text-muted"><?=e($summary['bdc_id'])?></div><div class="small mt-1">Novice <?=number_format((float)$summary['novice_points'],1)?> · Intermediate <?=number_format((float)$summary['intermediate_points'],1)?> · Advanced <?=number_format((float)$summary['advanced_points'],1)?></div></div></div></div></div><?php endforeach;?></div></div></section><?php endif;?><section class="card results-card"><div class="card-header bg-white"><strong><?=e(danceResultLabel($dance))?> Participant Results</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Date</th><th>Competitor</th><th>Event</th><th>Division</th><th>Role</th><th>Placement</th><th>Partner</th><th class="text-end">Points</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['event_date']?:'—')?></td><td><a class="fw-semibold text-dark" href="<?=e(url('/competitor/?id='.(int)$row['competitor_id'].'&dance='.$dance))?>"><?=e($row['exact_name'])?></a><div class="small text-muted"><?=e($row['bdc_id'])?></div></td><td><?=e($row['event_name'])?></td><td><?=e(ucwords(str_replace('_',' ',(string)$row['division'])))?></td><td><?=e(ucfirst((string)$row['dance_role']))?></td><td><?=e($row['placement']?:'—')?></td><td><?=e($row['partner_name']?:'—')?></td><td class="text-end fw-semibold"><?=number_format((float)$row['points_awarded'],1)?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted py-5">No <?=e(danceResultLabel($dance))?> participant results found.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?></main></body></html>